function esc(s){ s=String(s==null?'':s); return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function polar(cx,cy,r,a){ return [cx+r*Math.cos(a), cy+r*Math.sin(a)]; }
function arcPath(cx,cy,r0,r1,a0,a1){
  var p0=polar(cx,cy,r1,a0), p1=polar(cx,cy,r1,a1), p2=polar(cx,cy,r0,a1), p3=polar(cx,cy,r0,a0);
  var large=(a1-a0)>Math.PI?1:0;
  return 'M '+p0[0].toFixed(2)+' '+p0[1].toFixed(2)+' A '+r1+' '+r1+' 0 '+large+' 1 '+p1[0].toFixed(2)+' '+p1[1].toFixed(2)+
         ' L '+p2[0].toFixed(2)+' '+p2[1].toFixed(2)+' A '+r0+' '+r0+' 0 '+large+' 0 '+p3[0].toFixed(2)+' '+p3[1].toFixed(2)+' Z';
}
function sunburstSvg(data){
  if(!data||!data.children||!data.children.length) return {error:'需 {name, children:[{name,value}]}'};
  var kids=data.children.map(function(c){ return {name:String(c.name||''), value:+c.value}; });
  if(kids.some(function(k){ return isNaN(k.value)||k.value<=0; })) return {error:'每个子项须有正 value'};
  var total=kids.reduce(function(a,b){return a+b.value;},0);
  var cx=110, cy=110, r1=95, r0=42, ang=-Math.PI/2;
  var pal=['#5E6AD2','#10B981','#F5A623','#EF4444','#22D3EE','#A78BFA','#F472B6','#34D399','#FBBF24','#60A5FA'];
  var parts=[];
  kids.forEach(function(k,i){
    var frac=k.value/total, a0=ang, a1=ang+frac*2*Math.PI; ang=a1;
    parts.push('<path d="'+arcPath(cx,cy,r0,r1,a0,a1)+'" fill="'+pal[i%pal.length]+'" stroke="#0A0A0B" stroke-width="1"/>');
    var mid=(a0+a1)/2, mr=(r0+r1)/2, pp=polar(cx,cy,mr,mid);
    parts.push('<text x="'+pp[0].toFixed(1)+'" y="'+pp[1].toFixed(1)+'" text-anchor="middle" font-size="10" fill="#fff">'+esc(k.name)+'</text>');
  });
  parts.push('<circle cx="'+cx+'" cy="'+cy+'" r="'+(r0-2)+'" fill="#141417" stroke="#3A3B3E"/>');
  parts.push('<text x="'+cx+'" y="'+(cy+4)+'" text-anchor="middle" font-size="11" fill="#A1A1AA">'+esc(data.name)+'</text>');
  var svg='<svg viewBox="0 0 220 220" xmlns="http://www.w3.org/2000/svg">'+parts.join('')+'</svg>';
  return {svg:svg, n:kids.length};
}
var EXPORTS={sunburstSvg:sunburstSvg};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SunburstForgePure = EXPORTS; }
